<?php require_once "backend/config/conexion.php"; $conn = conectar(); $stmt = $conn->prepare("SELECT m.*, c.Color, c.Icono, c.id as Categoria_id, CAST(GROUP_CONCAT(mc2.Categoria_id) AS CHAR) as Todas_Categorias FROM marcador m LEFT JOIN marcador_categoria mc ON m.id = mc.Marcador_id AND mc.Es_principal = 1 LEFT JOIN categoria c ON mc.Categoria_id = c.id LEFT JOIN marcador_categoria mc2 ON m.id = mc2.Marcador_id WHERE m.Usuario_id = 1 GROUP BY m.id LIMIT 5"); $stmt->execute(); echo json_encode($stmt->fetchAll(PDO::FETCH_ASSOC)); ?>
